verification_commands.ac1:
set -u
F=docs/criteria/scoring_map/telemetry.md
test -f "$F" || { echo "ac1 RED: $F missing - this card's whole deliverable is this file"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Observability[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac1 RED: no '## Observability' section - the rubric grades metrics, traces and structured logs sharing a trace ID"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac1 RED: no '- Claim: N/M' line in the exact record format"; exit 1; }
set -- $CL
[ "$2" = "2" ] || { echo "ac1 RED: the Observability maximum is 2 per the grading rubric, not $2 - do not invent a scale"; exit 1; }
[ "$1" -le "$2" ] || { echo "ac1 RED: the claim $1/$2 exceeds its maximum"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac1 RED: no single backticked First entry point"; exit 1; }
[ "$(printf "%s\n" "$S" | grep -cE '^- First entry point:')" = "1" ] || { echo "ac1 RED: more than one First entry point line"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac1 RED: first entry point '$EP' does not exist on this tree"; exit 1; } ;; esac
# --- MEASURE the three legs the rubric names, then cap the claim to what is true
METRICS=0; grep -qE 'expense_created_total|/metrics' "$F" && METRICS=1
LOGS=0; grep -qiE 'ops/logging[.]md|structured log|JSON' "$F" && LOGS=1
TRACEID=0
if grep -rqiE "trace_id|traceparent|trace id" ops observability backend/app 2>/dev/null; then TRACEID=1; fi
echo "ac1 evidence: measured legs metrics_documented=$METRICS structured_logs_documented=$LOGS shared_trace_id_present=$TRACEID"
[ "$METRICS" = "1" ] || { echo "ac1 RED: the record claims observability without naming a metric or the exposition endpoint"; exit 1; }
[ "$LOGS" = "1" ] || { echo "ac1 RED: the record never names the structured-log surface (ops/logging.md) - half the rubric clause"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'grafana|prometheus|dashboard' || { echo "ac1 RED: the record says nothing about where telemetry is collected, stored and viewable in a UI - that is the second half of the rubric clause and the project has a real Grafana/Prometheus stack to point at"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'pii|credential|secret|never-log|never log|redact' || { echo "ac1 RED: the record never addresses the no-PII-no-credentials-in-telemetry clause - ops/logging.md carries an explicit never-log list and the claim is incomplete without it"; exit 1; }
if [ "$TRACEID" = "0" ]; then
  [ "$1" -lt "$2" ] || { echo "ac1 RED: the section claims $1/$2 but a shared trace ID does NOT exist on this tree (grep for trace_id/traceparent across ops, observability and backend/app returns nothing) and the traces stack is commented out in observability/README.md - claiming the full 2/2 asserts a correlation the reader cannot find in 30 seconds anywhere"; exit 1; }
  G=$(printf "%s\n" "$S" | sed -n 's/^- Gap:[[:space:]]*\(.*\)$/\1/p')
  [ -n "$G" ] || { echo "ac1 RED: the claim is below the maximum with no '- Gap:' line - an unexplained shortfall reads as laziness, not honesty, and a grader cannot tell what would close it"; exit 1; }
  printf "%s\n" "$G" | grep -qiE 'trac' || { echo "ac1 RED: the Gap line does not name the missing trace / trace-ID correlation, which is the specific clause the shortfall pays for"; exit 1; }
  printf "%s\n" "$S" | grep -qiE 'commented out|not enabled|carried as commented' || { echo "ac1 RED: the record must disclose that the traces/logs stack is carried as COMMENTED YAML rather than silently omit it - the decision is visible in observability/README.md and the map should say so"; exit 1; }
  echo "ac1 evidence: claim $1/$2 is below the maximum and the trace gap is priced, matching the measured tree"
else
  echo "ac1 evidence: a shared trace ID was found on the tree - re-read the rubric clause and re-measure before claiming 2/2"
fi
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac1 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac1 GREEN: OBSERVABILITY recorded honestly - claim $1/$2 capped by the measured tree, one existing first entry point ($EP), metrics + structured logs + the collection/storage/UI stack named, the no-PII clause addressed, every evidence path resolves, and the trace-ID gap priced in one line"

verification_commands.ac2:
set -u
F=docs/criteria/scoring_map/telemetry.md
test -f "$F" || { echo "ac2 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Alerting on User Impact[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac2 RED: no '## Alerting on User Impact' section - the rubric names this dimension verbatim at 0-1"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac2 RED: no '- Claim: N/M' line"; exit 1; }
set -- $CL
[ "$2" = "1" ] || { echo "ac2 RED: the Alerting maximum is 1 per the grading rubric, not $2 - this is the dimension where an invented scale is most tempting because 1 looks too small to be worth claiming"; exit 1; }
[ "$1" -le "$2" ] || { echo "ac2 RED: the claim $1/$2 exceeds its maximum"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac2 RED: no single backticked First entry point"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac2 RED: first entry point '$EP' does not exist"; exit 1; } ;; esac
# the alert rules the claim rests on must be countable on the tree RIGHT NOW
RULES=$(grep -cE "^[[:space:]]*-?[[:space:]]*alert:" observability/alerts.yaml 2>/dev/null || echo 0)
[ "${RULES:-0}" -ge 1 ] || { echo "ac2 RED: observability/alerts.yaml declares $RULES alert rules - the Alerting claim has nothing under it"; exit 1; }
echo "ac2 evidence: alert rules declared on the tree=$RULES"
printf "%s\n" "$S" | grep -qE 'observability/alerts[.]yaml' || { echo "ac2 RED: the record does not name observability/alerts.yaml - the single source of truth for alert names"; exit 1; }
printf "%s\n" "$S" | grep -qE 'HighExpenseCreationFailures|DBFallbackActive' || { echo "ac2 RED: the record names no concrete alert - a dimension claimed at full marks must be locatable at a specific rule in 30 seconds"; exit 1; }
printf "%s\n" "$S" | grep -qiE "user impact|user-visible|user visible|creation fail|fallback" || { echo "ac2 RED: the record never connects the alert to USER impact - the rubric's clause is 'alerting on user impact', not 'a yaml file exists'"; exit 1; }
printf "%s\n" "$S" | grep -qE 'incident-response/incidents/[0-9]{4}-[0-9]{2}-[0-9]{2}-[a-z0-9-]+' || { echo "ac2 RED: the record cites no dated incident directory - 'a drill happened' is prose, the dated path incident-response/incidents/<yyyy-mm-dd>-<id> is evidence, and the fence can only re-measure the latter"; exit 1; }
test -d incident-response/incidents/2026-10-17-db-fallback-01 || { echo "ac2 RED: the incident record the claim leans on is gone from the tree"; exit 1; }
NA=$(ls incident-response/incidents/2026-10-17-db-fallback-01 2>/dev/null | wc -l | tr -d " ")
[ "${NA:-0}" -ge 5 ] || { echo "ac2 RED: the drill directory holds $NA artifacts, fewer than the 5 the verification report records - the drill evidence is not intact"; exit 1; }
echo "ac2 evidence: drill artifacts present=$NA"
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac2 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac2 GREEN: ALERTING recorded - claim $1/$2 at the rubric maximum, backed by $RULES real alert rules, a named rule, the user-impact connection stated, and the measured drill record ($NA artifacts) that proves the path fires"

verification_commands.ac3:
set -u
F=docs/criteria/scoring_map/telemetry.md
test -f "$F" || { echo "ac3 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## On-Call Agent[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac3 RED: no '## On-Call Agent' section - the rubric names this dimension verbatim at 0-2"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac3 RED: no '- Claim: N/M' line"; exit 1; }
set -- $CL
[ "$2" = "2" ] || { echo "ac3 RED: the On-Call Agent maximum is 2 per the grading rubric, not $2"; exit 1; }
[ "$1" -le "$2" ] || { echo "ac3 RED: the claim $1/$2 exceeds its maximum"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac3 RED: no single backticked First entry point"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac3 RED: first entry point '$EP' does not exist"; exit 1; } ;; esac
printf "%s\n" "$S" | grep -qE 'incident-response/responder-task[.]md|incident-response/autonomy-policy[.]yaml' || { echo "ac3 RED: the record names neither the responder task nor the autonomy policy - those two files ARE the on-call agent"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'response[.]schema[.]json|validate_response[.]py|machine' || { echo "ac3 RED: the record says nothing about the machine-checkable answer shape - that is what makes the agent's output verifiable rather than prose"; exit 1; }
# --- MEASURE whether the agent is permitted to remediate, then cap the claim
READONLY=0
grep -qiE "READ-ONLY|must not attempt to fix|a human operates" incident-response/responder-task.md && READONLY=1
DENYFIX=0
grep -qE "denied_actions" incident-response/autonomy-policy.yaml && { grep -qE "restart_production|database_mutation" incident-response/autonomy-policy.yaml && DENYFIX=1; }
echo "ac3 evidence: measured remediation authority responder_readonly=$READONLY destructive_actions_denied=$DENYFIX"
if [ "$READONLY" = "1" ] || [ "$DENYFIX" = "1" ]; then
  [ "$1" -lt "$2" ] || { echo "ac3 RED: the section claims $1/$2, but the tree says the responder is READ-ONLY ('You diagnose; a human operates') and its policy denies restart_production and database_mutation with default_decision deny - the rubric's second point is 'fixes the issue', and claiming it would assert a capability the project deliberately and documentedly refuses"; exit 1; }
  G=$(printf "%s\n" "$S" | sed -n 's/^- Gap:[[:space:]]*\(.*\)$/\1/p')
  [ -n "$G" ] || { echo "ac3 RED: the claim is below the maximum with no '- Gap:' line"; exit 1; }
  printf "%s\n" "$G" | grep -qiE "fix|remediat|human|read-only|deny|denied" || { echo "ac3 RED: the Gap line does not name the human-operates remediation boundary the shortfall pays for"; exit 1; }
  printf "%s\n" "$S" | grep -qiE "read-only|diagnos" || { echo "ac3 RED: the record never states what the agent DOES do (diagnose, collect evidence, report) - understating the real half while pricing the missing half is not honesty, it is just loss"; exit 1; }
  echo "ac3 evidence: claim $1/$2 is below the maximum and the human-operates boundary is priced, matching the policy on the tree"
else
  echo "ac3 evidence: the responder task no longer declares a read-only boundary - re-read the policy and re-measure before claiming below the maximum"
fi
test -f incident-response/collect-evidence.sh || { echo "ac3 RED: the evidence-collection entry point is gone"; exit 1; }
printf "%s\n" "$S" | grep -qiE "collect-evidence|evidence" || { echo "ac3 RED: the record never names the evidence bundle the agent wakes on"; exit 1; }
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac3 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac3 GREEN: ON-CALL AGENT recorded honestly - claim $1/$2 capped by the measured autonomy policy, the wake-on-alert and machine-validated diagnosis claimed, the human-operates fix priced in one line, every evidence path resolves"
